package vn.xuannhashop.infrastructure.persistence;
import java.util.*;
import org.springframework.stereotype.Repository;
import vn.xuannhashop.business.inventory.application.*;
import vn.xuannhashop.business.inventory.application.StockOperationsApplication.*;
import vn.xuannhashop.business.shared.DomainException;
import static vn.xuannhashop.infrastructure.persistence.Sql.p;
@Repository
public class JdbcStockOperationsRepository implements StockOperationsRepository {
    private final Sql s;public JdbcStockOperationsRepository(Sql s){this.s=s;}
    public Map<String,Object> overview(){
        var receipts=s.rows("select r.*,w.name warehouse,t.name type_name,(select count(*) from purchase_receipt_line l where l.receipt_id=r.id) quantity from purchase_receipt r join warehouse w on w.id=r.warehouse_id join equipment_type t on t.id=r.type_id order by r.created_at desc limit 300",Map.of());
        for(var r:receipts)r.put("lines",s.rows("select * from purchase_receipt_line where receipt_id=:id order by code",p("id",r.get("id"))));
        var counts=s.rows("select c.*,w.name warehouse from stock_count c join warehouse w on w.id=c.warehouse_id order by c.created_at desc limit 100",Map.of());
        for(var c:counts)c.put("lines",countLines((UUID)c.get("id")));
        return Map.of("warehouses",s.rows("select w.*,count(e.id) asset_count from warehouse w left join equipment e on e.warehouse_id=w.id and e.state<>'DISPOSED' group by w.id order by w.name",Map.of()),"receipts",receipts,"actions",s.rows("select a.*,e.code,w.name from_name,d.name to_name from stock_action a join equipment e on e.id=a.equipment_id join warehouse w on w.id=a.from_warehouse left join warehouse d on d.id=a.to_warehouse order by a.created_at desc limit 300",Map.of()),"counts",counts);
    }
    public void warehouse(UUID id,String name,String address){s.update("insert into warehouse(id,name,address) values(:id,:n,:a)",p("id",id,"n",name,"a",address));}
    public void lockWarehouses(List<UUID> ids){var distinct=ids.stream().distinct().sorted().toList();if(s.rows("select id from warehouse where id in (:ids) order by id for update",p("ids",distinct)).size()!=distinct.size())throw DomainException.missing();}
    public Map<String,Object> asset(UUID id){return s.one("select * from equipment where id=:id",p("id",id));}
    public boolean activeType(UUID id){return s.one("select id from equipment_type where id=:id and active",p("id",id))!=null;}
    public void receive(UUID id,Receipt c,String actor){s.update("insert into purchase_receipt(id,warehouse_id,type_id,supplier_name,document_ref,acquired_on,warranty_until,useful_life_months,unit_cost,requested_by,reason) values(:id,:w,:t,:s,:d,:a,:until,:life,:cost,:actor,:reason)",p("id",id,"w",c.warehouseId(),"t",c.typeId(),"s",c.supplierName().strip(),"d",c.documentRef().strip(),"a",c.acquiredOn(),"until",c.warrantyUntil(),"life",c.usefulLifeMonths(),"cost",c.unitCost(),"actor",actor,"reason",c.reason()));for(var l:c.lines())s.update("insert into purchase_receipt_line(id,receipt_id,code,serial_number) values(:id,:r,:c,:s)",p("id",UUID.randomUUID(),"r",id,"c",l.code(),"s",l.serialNumber()));}
    public Map<String,Object> receipt(UUID id){return s.one("select * from purchase_receipt where id=:id for update",p("id",id));}
    public void decideReceipt(UUID id,boolean accepted,String actor,String note){var r=receipt(id);if(accepted)for(var l:s.rows("select * from purchase_receipt_line where receipt_id=:id order by code",p("id",id))){UUID e=UUID.randomUUID();s.update("insert into equipment(id,code,type_id,warehouse_id,state,serial_number,acquired_on,purchase_cost,useful_life_months,warranty_until,supplier_name,document_ref) values(:id,:code,:type,:warehouse,'AWAIT_ACCEPTANCE',:serial,:date,:cost,:life,:until,:supplier,:document)",p("id",e,"code",l.get("code"),"type",r.get("type_id"),"warehouse",r.get("warehouse_id"),"serial",l.get("serial_number"),"date",r.get("acquired_on"),"cost",r.get("unit_cost"),"life",r.get("useful_life_months"),"until",r.get("warranty_until"),"supplier",r.get("supplier_name"),"document",r.get("document_ref")));s.update("update purchase_receipt_line set equipment_id=:e where id=:id",p("e",e,"id",l.get("id")));}s.update("update purchase_receipt set status=:s,decided_by=:a,decision_note=:n,decided_at=clock_timestamp() where id=:id",p("id",id,"s",accepted?"ACCEPTED":"REJECTED","a",actor,"n",note));}
    public void action(UUID id,Action c,Map<String,Object> a,String actor){s.update("insert into stock_action(id,kind,equipment_id,from_warehouse,to_warehouse,previous_state,recovery_value,reason,requested_by) values(:id,:k,:e,:f,:t,:previous,:v,:r,:a)",p("id",id,"k",c.kind(),"e",c.equipmentId(),"f",a.get("warehouse_id"),"t",c.toWarehouse(),"previous",a.get("state"),"v",c.recoveryValue(),"r",c.reason(),"a",actor));s.update("update equipment set state='SUSPENDED',version=version+1 where id=:id",p("id",c.equipmentId()));}
    public Map<String,Object> action(UUID id){return s.one("select * from stock_action where id=:id for update",p("id",id));}
    public void decideAction(UUID id,boolean accepted,String actor,String note){var c=action(id);s.update("update equipment set warehouse_id=:w,state=:s,version=version+1 where id=:e",p("e",c.get("equipment_id"),"w",accepted&&c.get("kind").equals("TRANSFER")?c.get("to_warehouse"):c.get("from_warehouse"),"s",accepted?(c.get("kind").equals("DISPOSE")?"DISPOSED":"AWAIT_INSPECTION"):c.get("previous_state")));s.update("update stock_action set status=:s,decided_by=:a,decision_note=:n,decided_at=clock_timestamp() where id=:id",p("id",id,"s",accepted?"COMPLETED":"REJECTED","a",actor,"n",note));}
    public List<Map<String,Object>> countAssets(UUID w){return s.rows("select e.* from equipment e where warehouse_id=:w and state not in ('RENTED','PREPARING','DISPOSED') and not exists(select 1 from stock_action a where a.equipment_id=e.id and a.status='PENDING') and not exists(select 1 from warranty_case w where w.equipment_id=e.id and w.status='OPEN') order by e.id",p("w",w));}
    public void count(UUID id,Count c,List<Map<String,Object>> assets,String actor){s.update("insert into stock_count(id,warehouse_id,observed_codes,reason,requested_by) values(:id,:w,:codes,:r,:a)",p("id",id,"w",c.warehouseId(),"codes",String.join("\n",c.observedCodes()),"r",c.reason(),"a",actor));for(var a:assets)s.update("insert into stock_count_line(count_id,equipment_id,code,version,expected_state,found) values(:id,:e,:c,:v,:s,:f)",p("id",id,"e",a.get("id"),"c",a.get("code"),"v",a.get("version"),"s",a.get("state"),"f",c.observedCodes().contains(a.get("code"))));}
    public Map<String,Object> count(UUID id){return s.one("select * from stock_count where id=:id for update",p("id",id));}
    public List<Map<String,Object>> countLines(UUID id){return s.rows("select * from stock_count_line where count_id=:id order by equipment_id",p("id",id));}
    public void decideCount(UUID id,boolean accepted,String actor,String note){if(accepted)s.update("update equipment set state='SUSPENDED',version=version+1 where id in (select equipment_id from stock_count_line where count_id=:id and not found)",p("id",id));s.update("update stock_count set status=:s,decided_by=:a,decision_note=:n,decided_at=clock_timestamp() where id=:id",p("id",id,"s",accepted?"APPROVED":"REJECTED","a",actor,"n",note));}
}
